// Helper function to count integers in the input sequence
function CountInt(values: seq<object>): int
    reads values
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= i <= |values|  // i is within bounds
        invariant count == CountInt(values[0..i])  // count of integers found so far
    {
        if (values[i] is int) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
